// Raft Consensus Algorithm - Node Implementation
// Part 1: Core Raft Node
// Purpose: Implement Raft consensus protocol for distributed consensus

// ============ Type Definitions ============

// LogEntry represents a single entry in the Raft log
struct LogEntry {
    term: i32,
    command: string,
    index: i32
}

// NodeState represents the state of a Raft node
// States: Follower, Candidate, Leader
enum NodeState {
    Follower,
    Candidate,
    Leader
}

// RaftNode represents a single node in the Raft cluster
struct RaftNode {
    nodeId: i32,
    currentTerm: i32,
    votedFor: i32,
    logs: array,
    commitIndex: i32,
    lastApplied: i32,
    state: NodeState,
    electionTimeout: i32,
    heartbeatInterval: i32,
    lastHeartbeat: i32,
    nextIndex: array,
    matchIndex: array
}

// ============ Node Initialization ============

fn create_raft_node(nodeId: i32) -> RaftNode {
    let node = RaftNode {
        nodeId: nodeId,
        currentTerm: 0,
        votedFor: -1,
        logs: [],
        commitIndex: 0,
        lastApplied: 0,
        state: NodeState.Follower,
        electionTimeout: 150 + (nodeId * 10),
        heartbeatInterval: 50,
        lastHeartbeat: 0,
        nextIndex: [],
        matchIndex: []
    };
    return node;
}

// ============ Term Management ============

fn update_current_term(node: RaftNode, newTerm: i32) -> RaftNode {
    if newTerm > node.currentTerm {
        node.currentTerm = newTerm;
        node.votedFor = -1;
        node.state = NodeState.Follower;
    }
    return node;
}

fn get_current_term(node: RaftNode) -> i32 {
    return node.currentTerm;
}

// ============ Log Management ============

fn append_log_entry(node: RaftNode, command: string) -> RaftNode {
    let entry = LogEntry {
        term: node.currentTerm,
        command: command,
        index: length(node.logs) + 1
    };
    push(node.logs, entry);
    return node;
}

fn get_log_length(node: RaftNode) -> i32 {
    return length(node.logs);
}

fn get_last_log_term(node: RaftNode) -> i32 {
    if length(node.logs) == 0 {
        return 0;
    }
    return node.logs[length(node.logs) - 1].term;
}

fn get_last_log_index(node: RaftNode) -> i32 {
    if length(node.logs) == 0 {
        return 0;
    }
    return node.logs[length(node.logs) - 1].index;
}

// ============ State Transitions ============

fn become_follower(node: RaftNode) -> RaftNode {
    node.state = NodeState.Follower;
    return node;
}

fn become_candidate(node: RaftNode) -> RaftNode {
    node.state = NodeState.Candidate;
    node.currentTerm = node.currentTerm + 1;
    node.votedFor = node.nodeId;
    return node;
}

fn become_leader(node: RaftNode, clusterSize: i32) -> RaftNode {
    node.state = NodeState.Leader;
    node.nextIndex = [];
    node.matchIndex = [];

    let i = 0;
    while i < clusterSize {
        push(node.nextIndex, get_last_log_index(node) + 1);
        push(node.matchIndex, 0);
        i = i + 1;
    }

    return node;
}

// ============ Vote Counting ============

fn count_votes(votes: array, quorumSize: i32) -> i32 {
    let count = 0;
    let i = 0;
    while i < length(votes) {
        if votes[i] == 1 {
            count = count + 1;
        }
        i = i + 1;
    }
    return count;
}

fn has_quorum(votes: array, clusterSize: i32) -> bool {
    let quorum = (clusterSize / 2) + 1;
    let count = count_votes(votes, quorum);
    return count >= quorum;
}

// ============ Commit Index Management ============

fn update_commit_index(node: RaftNode, clusterSize: i32) -> RaftNode {
    let newCommitIndex = node.commitIndex;
    let n = node.commitIndex + 1;

    while n <= get_last_log_index(node) {
        let replicas = 1; // Count leader itself
        let i = 0;
        while i < length(node.matchIndex) {
            if i != node.nodeId && node.matchIndex[i] >= n {
                replicas = replicas + 1;
            }
            i = i + 1;
        }

        let quorum = (clusterSize / 2) + 1;
        if replicas >= quorum && node.logs[n - 1].term == node.currentTerm {
            newCommitIndex = n;
        }
        n = n + 1;
    }

    node.commitIndex = newCommitIndex;
    return node;
}

// ============ Election Timeout ============

fn should_start_election(node: RaftNode, currentTime: i32) -> bool {
    let timeSinceLastHeartbeat = currentTime - node.lastHeartbeat;
    return timeSinceLastHeartbeat >= node.electionTimeout && node.state == NodeState.Follower;
}

fn reset_election_timer(node: RaftNode, currentTime: i32) -> RaftNode {
    node.lastHeartbeat = currentTime;
    return node;
}

// ============ Validation ============

fn can_vote_for(node: RaftNode, candidateTerm: i32, candidateLastLogIndex: i32, candidateLastLogTerm: i32) -> bool {
    // Rule 1: Only vote if term is current
    if candidateTerm < node.currentTerm {
        return false;
    }

    // Rule 2: Only vote once per term
    if candidateTerm == node.currentTerm && node.votedFor != -1 && node.votedFor != candidateTerm {
        return false;
    }

    // Rule 3: Candidate must have at least as up-to-date log
    let lastLogIndex = get_last_log_index(node);
    let lastLogTerm = get_last_log_term(node);

    if candidateLastLogTerm < lastLogTerm {
        return false;
    }

    if candidateLastLogTerm == lastLogTerm && candidateLastLogIndex < lastLogIndex {
        return false;
    }

    return true;
}

// ============ Module Exports ============

fn mod_raft_node_create(nodeId: i32) -> RaftNode {
    return create_raft_node(nodeId);
}

fn mod_raft_node_get_term(node: RaftNode) -> i32 {
    return get_current_term(node);
}

fn mod_raft_node_append_log(node: RaftNode, command: string) -> RaftNode {
    return append_log_entry(node, command);
}

fn mod_raft_node_become_leader(node: RaftNode, clusterSize: i32) -> RaftNode {
    return become_leader(node, clusterSize);
}

fn mod_raft_node_update_commit(node: RaftNode, clusterSize: i32) -> RaftNode {
    return update_commit_index(node, clusterSize);
}

// Raft Consensus Algorithm - Consensus Implementation
// Part 2: Leader Election and Replication
// Purpose: Implement Raft consensus with leader election and log replication

// ============ Type Definitions ============

// AppendEntriesRequest for log replication
struct AppendEntriesRequest {
    term: i32,
    leaderId: i32,
    prevLogIndex: i32,
    prevLogTerm: i32,
    entries: array,
    leaderCommit: i32
}

// AppendEntriesResponse for log replication confirmation
struct AppendEntriesResponse {
    term: i32,
    success: bool,
    conflictIndex: i32,
    conflictTerm: i32
}

// RequestVoteRequest for election voting
struct RequestVoteRequest {
    term: i32,
    candidateId: i32,
    lastLogIndex: i32,
    lastLogTerm: i32
}

// RequestVoteResponse for election voting confirmation
struct RequestVoteResponse {
    term: i32,
    voteGranted: bool
}

// RaftConsensus represents the consensus state
struct RaftConsensus {
    node: RaftNode,
    electionVotes: array,
    appendReplies: array,
    clusterSize: i32,
    electionState: i32,
    lastElectionTime: i32
}

// ============ Consensus Initialization ============

fn create_consensus(nodeId: i32, clusterSize: i32) -> RaftConsensus {
    let consensus = RaftConsensus {
        node: create_raft_node(nodeId),
        electionVotes: [],
        appendReplies: [],
        clusterSize: clusterSize,
        electionState: 0,
        lastElectionTime: 0
    };
    return consensus;
}

// ============ Leader Election ============

fn start_election(consensus: RaftConsensus, currentTime: i32) -> RaftConsensus {
    consensus.node = become_candidate(consensus.node);
    consensus.electionVotes = [];
    consensus.lastElectionTime = currentTime;

    // Candidate votes for itself
    push(consensus.electionVotes, 1);

    // Reset other votes to 0
    let i = 1;
    while i < consensus.clusterSize {
        push(consensus.electionVotes, 0);
        i = i + 1;
    }

    return consensus;
}

fn process_vote_response(consensus: RaftConsensus, fromNodeId: i32, response: RequestVoteResponse) -> RaftConsensus {
    // Update term if needed
    if response.term > consensus.node.currentTerm {
        consensus.node = update_current_term(consensus.node, response.term);
        consensus.node = become_follower(consensus.node);
    }

    // Record vote if granted
    if response.voteGranted && consensus.node.state == NodeState.Candidate {
        consensus.electionVotes[fromNodeId] = 1;
    }

    return consensus;
}

fn check_election_won(consensus: RaftConsensus) -> bool {
    if consensus.node.state != NodeState.Candidate {
        return false;
    }

    let quorum = (consensus.clusterSize / 2) + 1;
    let voteCount = 0;
    let i = 0;
    while i < length(consensus.electionVotes) {
        if consensus.electionVotes[i] == 1 {
            voteCount = voteCount + 1;
        }
        i = i + 1;
    }

    return voteCount >= quorum;
}

// ============ Log Replication ============

fn create_append_entries_request(consensus: RaftConsensus, prevLogIndex: i32, prevLogTerm: i32) -> AppendEntriesRequest {
    let request = AppendEntriesRequest {
        term: consensus.node.currentTerm,
        leaderId: consensus.node.nodeId,
        prevLogIndex: prevLogIndex,
        prevLogTerm: prevLogTerm,
        entries: [],
        leaderCommit: consensus.node.commitIndex
    };
    return request;
}

fn process_append_entries_request(consensus: RaftConsensus, request: AppendEntriesRequest) -> RaftConsensus {
    let response = AppendEntriesResponse {
        term: consensus.node.currentTerm,
        success: false,
        conflictIndex: 0,
        conflictTerm: 0
    };

    // Rule 1: Reply false if term is less than request term
    if request.term < consensus.node.currentTerm {
        response.term = consensus.node.currentTerm;
        response.success = false;
        return consensus;
    }

    // Update term if needed
    if request.term > consensus.node.currentTerm {
        consensus.node = update_current_term(consensus.node, request.term);
    }

    // Reset election timer
    consensus.node = reset_election_timer(consensus.node, get_current_time());

    // Rule 2: Check log consistency
    let logLength = get_log_length(consensus.node);
    if request.prevLogIndex > 0 && request.prevLogIndex > logLength {
        response.success = false;
        response.conflictIndex = logLength + 1;
        return consensus;
    }

    if request.prevLogIndex > 0 {
        let prevEntry = consensus.node.logs[request.prevLogIndex - 1];
        if prevEntry.term != request.prevLogTerm {
            response.success = false;
            response.conflictTerm = prevEntry.term;
            response.conflictIndex = request.prevLogIndex;
            return consensus;
        }
    }

    // Rule 3: Append entries
    let i = 0;
    while i < length(request.entries) {
        let entry = request.entries[i];
        let index = request.prevLogIndex + i + 1;

        if index > logLength {
            push(consensus.node.logs, entry);
        } else {
            if consensus.node.logs[index - 1].term != entry.term {
                // Truncate and append
                consensus.node.logs[index - 1] = entry;
            }
        }
        i = i + 1;
    }

    // Rule 4: Update commit index
    if request.leaderCommit > consensus.node.commitIndex {
        let newCommit = request.leaderCommit;
        let logLength = get_log_length(consensus.node);
        if newCommit > logLength {
            newCommit = logLength;
        }
        consensus.node.commitIndex = newCommit;
    }

    response.success = true;
    response.term = consensus.node.currentTerm;
    return consensus;
}

fn process_append_entries_response(consensus: RaftConsensus, fromNodeId: i32, response: AppendEntriesResponse) -> RaftConsensus {
    // Update term if needed
    if response.term > consensus.node.currentTerm {
        consensus.node = update_current_term(consensus.node, response.term);
        consensus.node = become_follower(consensus.node);
        return consensus;
    }

    // Only leader processes append responses
    if consensus.node.state != NodeState.Leader {
        return consensus;
    }

    if response.success {
        // Update matchIndex and nextIndex
        consensus.node.matchIndex[fromNodeId] = consensus.node.nextIndex[fromNodeId] - 1;
        consensus.node.nextIndex[fromNodeId] = consensus.node.nextIndex[fromNodeId] + 1;

        // Update commitIndex
        consensus.node = update_commit_index(consensus.node, consensus.clusterSize);
    } else {
        // Decrease nextIndex for conflict
        if consensus.node.nextIndex[fromNodeId] > 1 {
            consensus.node.nextIndex[fromNodeId] = consensus.node.nextIndex[fromNodeId] - 1;
        }
    }

    return consensus;
}

// ============ Request Vote Processing ============

fn create_request_vote_request(consensus: RaftConsensus) -> RequestVoteRequest {
    let request = RequestVoteRequest {
        term: consensus.node.currentTerm,
        candidateId: consensus.node.nodeId,
        lastLogIndex: get_last_log_index(consensus.node),
        lastLogTerm: get_last_log_term(consensus.node)
    };
    return request;
}

fn process_request_vote_request(consensus: RaftConsensus, request: RequestVoteRequest) -> RaftConsensus {
    let response = RequestVoteResponse {
        term: consensus.node.currentTerm,
        voteGranted: false
    };

    // Rule 1: Reply false if term is less
    if request.term < consensus.node.currentTerm {
        response.term = consensus.node.currentTerm;
        response.voteGranted = false;
        return consensus;
    }

    // Update term if needed
    if request.term > consensus.node.currentTerm {
        consensus.node = update_current_term(consensus.node, request.term);
    }

    // Rule 2: Check if can vote
    if can_vote_for(consensus.node, request.term, request.lastLogIndex, request.lastLogTerm) {
        consensus.node.votedFor = request.candidateId;
        response.voteGranted = true;
        consensus.node = reset_election_timer(consensus.node, get_current_time());
    }

    response.term = consensus.node.currentTerm;
    return consensus;
}

// ============ Utility Functions ============

fn get_current_time() -> i32 {
    return 0; // Placeholder - should be system time
}

// ============ Module Exports ============

fn mod_consensus_create(nodeId: i32, clusterSize: i32) -> RaftConsensus {
    return create_consensus(nodeId, clusterSize);
}

fn mod_consensus_start_election(consensus: RaftConsensus, currentTime: i32) -> RaftConsensus {
    return start_election(consensus, currentTime);
}

fn mod_consensus_check_election_won(consensus: RaftConsensus) -> bool {
    return check_election_won(consensus);
}

fn mod_consensus_process_vote_response(consensus: RaftConsensus, fromNodeId: i32, response: RequestVoteResponse) -> RaftConsensus {
    return process_vote_response(consensus, fromNodeId, response);
}

fn mod_consensus_process_append_entries_request(consensus: RaftConsensus, request: AppendEntriesRequest) -> RaftConsensus {
    return process_append_entries_request(consensus, request);
}

// Distributed Database Implementation using Raft
// Part 3: State Machine and Database Operations
// Purpose: Implement a distributed key-value database using Raft consensus

// ============ Type Definitions ============

// Command types for the state machine
enum CommandType {
    Get,
    Set,
    Delete,
    Exists
}

// DBCommand represents a command to apply to the state machine
struct DBCommand {
    commandType: CommandType,
    key: string,
    value: string,
    timestamp: i32
}

// DBResponse represents the response from a database operation
struct DBResponse {
    success: bool,
    value: string,
    error: string,
    term: i32
}

// StateMachine represents the key-value store state machine
struct StateMachine {
    data: array,
    lastAppliedIndex: i32,
    lastAppliedTerm: i32
}

// DistributedDB combines Raft consensus with state machine
struct DistributedDB {
    consensus: RaftConsensus,
    stateMachine: StateMachine,
    uncommittedCommands: array,
    responses: array
}

// ============ State Machine Initialization ============

fn create_state_machine() -> StateMachine {
    let sm = StateMachine {
        data: [],
        lastAppliedIndex: 0,
        lastAppliedTerm: 0
    };
    return sm;
}

// ============ Database Operations ============

fn db_set(db: DistributedDB, key: string, value: string, timestamp: i32) -> DistributedDB {
    // Only leader can accept writes
    if db.consensus.node.state != NodeState.Leader {
        let response = DBResponse {
            success: false,
            value: "",
            error: "Not leader",
            term: db.consensus.node.currentTerm
        };
        push(db.responses, response);
        return db;
    }

    // Create command
    let command = DBCommand {
        commandType: CommandType.Set,
        key: key,
        value: value,
        timestamp: timestamp
    };

    // Append to log
    let commandStr = "SET:" + key + ":" + value;
    db.consensus.node = append_log_entry(db.consensus.node, commandStr);

    // Store uncommitted command for tracking
    push(db.uncommittedCommands, command);

    let response = DBResponse {
        success: true,
        value: "",
        error: "",
        term: db.consensus.node.currentTerm
    };
    push(db.responses, response);
    return db;
}

fn db_get(db: DistributedDB, key: string) -> DistributedDB {
    // Get can be served by any node with current term (read from state machine)
    let value = "";
    let found = false;

    let i = 0;
    while i < length(db.stateMachine.data) {
        let entry = db.stateMachine.data[i];
        if entry.key == key {
            value = entry.value;
            found = true;
        }
        i = i + 1;
    }

    let response = DBResponse {
        success: found,
        value: value,
        error: if found then "" else "Key not found",
        term: db.consensus.node.currentTerm
    };
    push(db.responses, response);
    return db;
}

fn db_delete(db: DistributedDB, key: string, timestamp: i32) -> DistributedDB {
    // Only leader can accept deletes
    if db.consensus.node.state != NodeState.Leader {
        let response = DBResponse {
            success: false,
            value: "",
            error: "Not leader",
            term: db.consensus.node.currentTerm
        };
        push(db.responses, response);
        return db;
    }

    // Create command
    let command = DBCommand {
        commandType: CommandType.Delete,
        key: key,
        value: "",
        timestamp: timestamp
    };

    // Append to log
    let commandStr = "DEL:" + key;
    db.consensus.node = append_log_entry(db.consensus.node, commandStr);

    // Store uncommitted command
    push(db.uncommittedCommands, command);

    let response = DBResponse {
        success: true,
        value: "",
        error: "",
        term: db.consensus.node.currentTerm
    };
    push(db.responses, response);
    return db;
}

// ============ State Machine Application ============

fn apply_committed_entries(db: DistributedDB) -> DistributedDB {
    let lastIndex = db.stateMachine.lastAppliedIndex;

    // Apply all committed entries
    while lastIndex < db.consensus.node.commitIndex {
        lastIndex = lastIndex + 1;

        if lastIndex > 0 && lastIndex <= get_log_length(db.consensus.node) {
            let entry = db.consensus.node.logs[lastIndex - 1];

            // Parse and apply command
            if starts_with(entry.command, "SET:") {
                let parts = split_string(entry.command, ":");
                if length(parts) >= 3 {
                    let key = parts[1];
                    let value = parts[2];

                    // Add or update in state machine
                    let found = false;
                    let i = 0;
                    while i < length(db.stateMachine.data) {
                        if db.stateMachine.data[i].key == key {
                            db.stateMachine.data[i].value = value;
                            found = true;
                        }
                        i = i + 1;
                    }

                    if !found {
                        let newEntry = DBCommand {
                            commandType: CommandType.Set,
                            key: key,
                            value: value,
                            timestamp: 0
                        };
                        push(db.stateMachine.data, newEntry);
                    }
                }
            } else if starts_with(entry.command, "DEL:") {
                let parts = split_string(entry.command, ":");
                if length(parts) >= 2 {
                    let key = parts[1];

                    // Remove from state machine
                    let i = 0;
                    while i < length(db.stateMachine.data) {
                        if db.stateMachine.data[i].key == key {
                            // Remove by shifting
                            let j = i;
                            while j < length(db.stateMachine.data) - 1 {
                                db.stateMachine.data[j] = db.stateMachine.data[j + 1];
                                j = j + 1;
                            }
                            // Pop last element
                            if length(db.stateMachine.data) > 0 {
                                db.stateMachine.data = take(db.stateMachine.data, length(db.stateMachine.data) - 1);
                            }
                        }
                        i = i + 1;
                    }
                }
            }

            db.stateMachine.lastAppliedIndex = lastIndex;
            db.stateMachine.lastAppliedTerm = entry.term;
        }
    }

    return db;
}

// ============ Distributed DB Initialization ============

fn create_distributed_db(nodeId: i32, clusterSize: i32) -> DistributedDB {
    let db = DistributedDB {
        consensus: create_consensus(nodeId, clusterSize),
        stateMachine: create_state_machine(),
        uncommittedCommands: [],
        responses: []
    };
    return db;
}

// ============ Utility Functions ============

fn starts_with(str: string, prefix: string) -> bool {
    // Simple string prefix check
    if length(str) < length(prefix) {
        return false;
    }
    let i = 0;
    while i < length(prefix) {
        if str[i] != prefix[i] {
            return false;
        }
        i = i + 1;
    }
    return true;
}

fn split_string(str: string, delimiter: string) -> array {
    // Simple string split
    let parts = [];
    let current = "";
    let i = 0;
    while i < length(str) {
        if str[i] == delimiter[0] {
            push(parts, current);
            current = "";
        } else {
            current = current + str[i];
        }
        i = i + 1;
    }
    if length(current) > 0 {
        push(parts, current);
    }
    return parts;
}

fn take(arr: array, n: i32) -> array {
    let result = [];
    let i = 0;
    while i < n && i < length(arr) {
        push(result, arr[i]);
        i = i + 1;
    }
    return result;
}

// ============ Health Check ============

fn is_leader(db: DistributedDB) -> bool {
    return db.consensus.node.state == NodeState.Leader;
}

fn get_current_term(db: DistributedDB) -> i32 {
    return db.consensus.node.currentTerm;
}

fn get_log_length(db: DistributedDB) -> i32 {
    return get_log_length(db.consensus.node);
}

fn get_commit_index(db: DistributedDB) -> i32 {
    return db.consensus.node.commitIndex;
}

// ============ Module Exports ============

fn mod_db_create(nodeId: i32, clusterSize: i32) -> DistributedDB {
    return create_distributed_db(nodeId, clusterSize);
}

fn mod_db_set(db: DistributedDB, key: string, value: string, timestamp: i32) -> DistributedDB {
    return db_set(db, key, value, timestamp);
}

fn mod_db_get(db: DistributedDB, key: string) -> DistributedDB {
    return db_get(db, key);
}

fn mod_db_delete(db: DistributedDB, key: string, timestamp: i32) -> DistributedDB {
    return db_delete(db, key, timestamp);
}

fn mod_db_apply_committed(db: DistributedDB) -> DistributedDB {
    return apply_committed_entries(db);
}

fn mod_db_is_leader(db: DistributedDB) -> bool {
    return is_leader(db);
}

// Raft Consensus DB - Comprehensive Test Suite
// 40 Unforgiving Tests covering 11 Rules
// Test Groups: A-D (10 tests each) + Summary

// ============ Global Test State ============

struct TestResult {
    name: string,
    passed: bool,
    message: string,
    rulesCovered: array
}

let test_results = [];
let total_tests = 0;
let passed_tests = 0;

// ============ Test Utilities ============

fn assert_equal(actual: i32, expected: i32, testName: string, rule: string) -> bool {
    total_tests = total_tests + 1;
    if actual == expected {
        passed_tests = passed_tests + 1;
        let result = TestResult {
            name: testName,
            passed: true,
            message: "Expected " + to_string(expected) + ", got " + to_string(actual),
            rulesCovered: [rule]
        };
        push(test_results, result);
        return true;
    } else {
        let result = TestResult {
            name: testName,
            passed: false,
            message: "Expected " + to_string(expected) + ", got " + to_string(actual),
            rulesCovered: [rule]
        };
        push(test_results, result);
        return false;
    }
}

fn assert_bool(actual: bool, expected: bool, testName: string, rule: string) -> bool {
    total_tests = total_tests + 1;
    if actual == expected {
        passed_tests = passed_tests + 1;
        let result = TestResult {
            name: testName,
            passed: true,
            message: "Expected " + to_string(expected) + ", got " + to_string(actual),
            rulesCovered: [rule]
        };
        push(test_results, result);
        return true;
    } else {
        let result = TestResult {
            name: testName,
            passed: false,
            message: "Expected " + to_string(expected) + ", got " + to_string(actual),
            rulesCovered: [rule]
        };
        push(test_results, result);
        return false;
    }
}

fn to_string(n: i32) -> string {
    if n == 0 { return "0"; }
    if n == 1 { return "1"; }
    if n == 2 { return "2"; }
    if n == 3 { return "3"; }
    if n == 4 { return "4"; }
    if n == 5 { return "5"; }
    return "unknown";
}

